/**
 * TeamPerformanceReport Component
 * Displays team member performance metrics
 */

import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import type { TeamPerformanceMember } from '../../../models/Report';
import styles from './TeamPerformanceReport.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

interface TeamPerformanceReportProps {
  data: TeamPerformanceMember[];
}

export const TeamPerformanceReport: React.FC<TeamPerformanceReportProps> = ({
  data,
}) => {
  const chartData = {
    labels: data.map((member) => member.name),
    datasets: [
      {
        label: 'Phiếu Yêu Cầu Đã Xử Lý',
        data: data.map((member) => member.ticketsResolved),
        backgroundColor: '#2563eb',
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    indexAxis: 'y' as const,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      x: {
        beginAtZero: true,
      },
    },
  };

  return (
    <div className={styles.reportCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>
          <i className="fas fa-users"></i>
          Hiệu Suất Nhóm
        </h3>
        <div className={styles.actions}>
          <button className={styles.filterButton}>
            <i className="fas fa-filter"></i> Filter
          </button>
          <button className={styles.exportButton}>
            <i className="fas fa-download"></i> Export
          </button>
        </div>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.chartContainer}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      </div>
    </div>
  );
};
