import React, { useState, useRef, useEffect, forwardRef, useImperativeHandle } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../../store/store';
import styles from './MentionInput.module.css';

export interface MentionInputRef {
  focus: () => void;
}

interface MentionInputProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  onSubmit?: () => void;
  className?: string;
}

interface MentionMatch {
  start: number;
  end: number;
  query: string;
}

export const MentionInput = forwardRef<MentionInputRef, MentionInputProps>(({
  value,
  onChange,
  placeholder = 'Nhập nội dung...',
  rows = 3,
  disabled = false,
  onSubmit,
  className = '',
}, ref) => {
  const [showDropdown, setShowDropdown] = useState(false);
  const [mentionMatch, setMentionMatch] = useState<MentionMatch | null>(null);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Expose focus method via ref
  useImperativeHandle(ref, () => ({
    focus: () => {
      textareaRef.current?.focus();
    },
  }));

  // Get users from Redux store
  const users = useSelector((state: RootState) => state.users.users);
  const currentUser = useSelector((state: RootState) => state.users.currentUser);

  // Filter users based on mention query
  const filteredUsers = mentionMatch
    ? users.filter((user) =>
        user.fullName.toLowerCase().includes(mentionMatch.query.toLowerCase()) ||
        (user.email && user.email.toLowerCase().includes(mentionMatch.query.toLowerCase()))
      )
    : [];

  // Detect @ mentions
  const detectMention = (text: string, cursorPos: number): MentionMatch | null => {
    // Find the last @ before cursor
    let mentionStart = -1;
    for (let i = cursorPos - 1; i >= 0; i--) {
      if (text[i] === '@') {
        mentionStart = i;
        break;
      }
      if (text[i] === ' ' || text[i] === '\n') {
        break;
      }
    }

    if (mentionStart === -1) return null;

    // Find the end of the mention (space, newline, or end of text)
    let mentionEnd = cursorPos;
    for (let i = cursorPos; i < text.length; i++) {
      if (text[i] === ' ' || text[i] === '\n') {
        mentionEnd = i;
        break;
      }
      mentionEnd = i + 1;
    }

    const query = text.substring(mentionStart + 1, mentionEnd);
    return { start: mentionStart, end: mentionEnd, query };
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newValue = e.target.value;
    onChange(newValue);

    const cursorPos = e.target.selectionStart;
    const match = detectMention(newValue, cursorPos);

    if (match && match.query.length > 0) {
      setMentionMatch(match);
      setShowDropdown(true);
      setSelectedIndex(0);
    } else {
      setShowDropdown(false);
      setMentionMatch(null);
    }
  };

  const insertMention = (userName: string) => {
    if (!mentionMatch || !textareaRef.current) return;

    const before = value.substring(0, mentionMatch.start);
    const after = value.substring(mentionMatch.end);
    const newValue = `${before}@${userName} ${after}`;

    onChange(newValue);
    setShowDropdown(false);
    setMentionMatch(null);

    // Set cursor position after mention
    setTimeout(() => {
      if (textareaRef.current) {
        const newCursorPos = mentionMatch.start + userName.length + 2; // +2 for @ and space
        textareaRef.current.setSelectionRange(newCursorPos, newCursorPos);
        textareaRef.current.focus();
      }
    }, 0);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (!showDropdown) {
      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && onSubmit) {
        e.preventDefault();
        onSubmit();
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((prev) => (prev + 1) % filteredUsers.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((prev) => (prev - 1 + filteredUsers.length) % filteredUsers.length);
        break;
      case 'Enter':
      case 'Tab':
        e.preventDefault();
        if (filteredUsers[selectedIndex]) {
          insertMention(filteredUsers[selectedIndex].fullName);
        }
        break;
      case 'Escape':
        e.preventDefault();
        setShowDropdown(false);
        setMentionMatch(null);
        break;
    }
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node) &&
        textareaRef.current &&
        !textareaRef.current.contains(e.target as Node)
      ) {
        setShowDropdown(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getAvatarColor = (userId: string) => {
    const colors = [
      '#3b82f6',
      '#8b5cf6',
      '#ec4899',
      '#f59e0b',
      '#10b981',
      '#06b6d4',
      '#6366f1',
    ];
    const hash = userId.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return colors[hash % colors.length];
  };

  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  return (
    <div className={`${styles.mentionInputContainer} ${className}`}>
      <textarea
        ref={textareaRef}
        className={styles.textarea}
        value={value}
        onChange={handleTextChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        rows={rows}
        disabled={disabled}
      />

      {showDropdown && filteredUsers.length > 0 && (
        <div ref={dropdownRef} className={styles.dropdown}>
          <div className={styles.dropdownHeader}>
            <i className="fas fa-at"></i>
            <span>Mention người dùng</span>
          </div>
          <div className={styles.userList}>
            {filteredUsers.map((user, index) => (
              <div
                key={user.id}
                className={`${styles.userItem} ${index === selectedIndex ? styles.selected : ''}`}
                onClick={() => insertMention(user.fullName)}
                onMouseEnter={() => setSelectedIndex(index)}
              >
                <div
                  className={styles.avatar}
                  style={{ backgroundColor: getAvatarColor(user.id) }}
                >
                  {getInitials(user.fullName)}
                </div>
                <div className={styles.userInfo}>
                  <div className={styles.userName}>{user.fullName}</div>
                  {user.email && <div className={styles.userEmail}>{user.email}</div>}
                </div>
                {user.id === currentUser?.id && (
                  <span className={styles.youBadge}>Bạn</span>
                )}
              </div>
            ))}
          </div>
          <div className={styles.dropdownFooter}>
            <kbd>↑↓</kbd> di chuyển <kbd>Enter</kbd> chọn <kbd>Esc</kbd> đóng
          </div>
        </div>
      )}
    </div>
  );
});

MentionInput.displayName = 'MentionInput';
