import {
  Ticket,
  TicketPriority,
  TicketStatus,
  TicketActivityItem,
  SLAInfo,
  SLAStatus,
  TicketHelper,
} from '../../models/Ticket';
import type { PaginatedResponse, UUID } from '../../models/common';
import type { BffTicketDto, BffTicketListItem, BffHelperDto, BffTicketActivityDto, BffPagedResult } from './responseModel';

// ── Status mapping ────────────────────────────────────────────────────────────

/**
 * BFF returns PascalCase status strings (e.g. "InProgress").
 * Map them to the frontend TicketStatus enum values (e.g. "in_progress").
 */
export const BFF_STATUS_MAP: Record<string, TicketStatus> = {
  Submitted:       TicketStatus.Submitted,
  Pending:         TicketStatus.Pending,
  Triaged:         TicketStatus.Triaged,
  Rejected:        TicketStatus.Rejected,
  Assigned:        TicketStatus.Assigned,
  InProgress:      TicketStatus.InProgress,
  HelpRequested:   TicketStatus.HelpRequested,
  SupportAssigned: TicketStatus.SupportAssigned,
  Blocked:         TicketStatus.Blocked,
  Resolved:        TicketStatus.Resolved,
  Approved:        TicketStatus.Approved,
  Reopened:        TicketStatus.Reopened,
  Closed:          TicketStatus.Closed,
};

export const mapStatus = (s: string): TicketStatus =>
  BFF_STATUS_MAP[s] ?? (s.toLowerCase() as TicketStatus);

// ── SLA helper ────────────────────────────────────────────────────────────────

/**
 * Derive SLAInfo from the ticket's dueDate and the BFF slaBreached flag.
 * The BFF does not yet return a full SLA breakdown, so we compute locally.
 */
export const computeSla = (dueDateStr: string, breached: boolean): SLAInfo => {
  const targetDate       = dueDateStr;
  const now              = new Date();
  const remainingMinutes = Math.max(
    0,
    Math.floor((new Date(dueDateStr).getTime() - now.getTime()) / 60_000)
  );
  const status: SLAStatus =
    breached || remainingMinutes === 0 ? SLAStatus.Breached
    : remainingMinutes < 20             ? SLAStatus.Danger
    : remainingMinutes < 60             ? SLAStatus.Warning
    :                                     SLAStatus.Safe;
  return { targetDate, remainingMinutes, percentage: 100, status, breached };
};

// ── Entity mappers ────────────────────────────────────────────────────────────

/** BFF TicketActivityDto → frontend TicketActivityItem */
export const mapActivity = (a: BffTicketActivityDto): TicketActivityItem => ({
  id:          a.id as UUID,
  type:        a.type,
  actor:       a.actorName,
  description: a.description,
  timestamp:   a.createdAt,
  fromStatus:  a.fromStatus ?? null,
  toStatus:    a.toStatus   ?? null,
});

/** BFF TicketHelperDto → frontend TicketHelper */
export const mapHelper = (h: BffHelperDto): TicketHelper => ({
  id:             h.id as UUID,
  userId:         h.userId as UUID,
  userName:       h.userName,
  assignedAt:     h.assignedAt,
  assignedById:   h.assignedById as UUID,
  assignedByName: h.assignedByName,
});

/**
 * BFF TicketResponseDto (full) → frontend Ticket.
 * Used after create, update and all action PATCH endpoints.
 */
export const mapBffTicket = (dto: BffTicketDto): Ticket => ({
  id:             dto.id as UUID,
  ticketNumber:   dto.ticketNumber,
  title:          dto.title,
  description:    dto.description,
  priority:       dto.priority.toLowerCase() as TicketPriority,
  status:         mapStatus(dto.status),
  category:       dto.category as Ticket['category'],
  departmentId:   dto.departmentId as UUID,
  departmentName: dto.departmentName,
  assigneeId:     (dto.assigneeId as UUID) ?? null,
  assigneeName:   dto.assigneeName ?? null,
  assignedAt:     dto.assignedAt ?? null,
  createdById:    dto.createdById as UUID,
  createdByName:  dto.createdByName,
  dueDate:        dto.dueDate,
  sla:            computeSla(dto.dueDate, dto.slaBreached),
  tags:           dto.tags ?? [],
  // BFF does not return these counts; they are fetched separately in TicketTabs
  attachmentCount: 0,
  commentCount:   0,
  submittedAt:    dto.submittedAt ?? undefined,
  triagedAt:      dto.triagedAt  ?? null,
  rejectionReason:         dto.rejectionReason ?? null,
  pendingReason:           dto.pendingReason ?? null,
  helpRequestDescription:  dto.helpRequestDescription ?? null,
  helpRequestedAt:         dto.helpRequestedAt ?? null,
  helpers:        (dto.helpers     ?? []).map(mapHelper),
  activities:     (dto.activities  ?? []).map(mapActivity),
  createdAt:      dto.createdAt,
  updatedAt:      dto.updatedAt,
});

/**
 * BFF TicketListItemDto (reduced) → frontend Ticket.
 * Used in paginated list responses — empty fields are left at defaults.
 */
export const mapBffListItem = (dto: BffTicketListItem): Ticket => ({
  id:             dto.id as UUID,
  ticketNumber:   dto.ticketNumber,
  title:          dto.title,
  description:    '',
  priority:       dto.priority.toLowerCase() as TicketPriority,
  status:         mapStatus(dto.status),
  category:       dto.category as Ticket['category'],
  departmentId:   dto.departmentId as UUID,
  departmentName: dto.departmentName,
  assigneeId:     (dto.assigneeId as UUID) ?? null,
  assigneeName:   dto.assigneeName ?? null,
  createdById:    '' as UUID,
  createdByName:  '',
  dueDate:        dto.dueDate,
  sla:            computeSla(dto.dueDate, dto.slaBreached),
  tags:           [],
  attachmentCount: 0,
  commentCount:   0,
  helpers:        [],
  createdAt:      dto.createdAt,
  updatedAt:      dto.updatedAt,
});

/** BFF TicketPagedResult → frontend PaginatedResponse<Ticket> */
export const mapPagedResult = (data: BffPagedResult): PaginatedResponse<Ticket> => ({
  items:      data.items.map(mapBffListItem),
  total:      data.totalCount,
  page:       data.page,
  pageSize:   data.pageSize,
  totalPages: data.totalPages,
});
