import { UUID, Timestamps } from './common';

// ─────────────────────────────────────────────────────────────────────────────
// Enums
// ─────────────────────────────────────────────────────────────────────────────

export enum IncidentReportType {
  Voluntary   = 'voluntary',
  Mandatory   = 'mandatory',
}

export enum IncidentOccurrenceStatus {
  NotOccurred = 'not_occurred',
  Occurred    = 'occurred',
}

export enum IncidentSeverity {
  Severe  = 'severe',
  Medium  = 'medium',
  Mild    = 'mild',
}

export enum NotificationStatus {
  Yes           = 'yes',
  No            = 'no',
  NotRecorded   = 'not_recorded',
}

export enum IncidentStatus {
  Draft      = 'draft',
  Submitted  = 'submitted',
  InAnalysis = 'in_analysis',
  Resolved   = 'resolved',
  Closed     = 'closed',
}

// ─────────────────────────────────────────────────────────────────────────────
// Section II – Nhóm sự cố (Incident type groups 1–11)
// ─────────────────────────────────────────────────────────────────────────────

/** Group 1: Thực hiện quy trình kỹ thuật, thủ thuật chuyên môn */
export interface IncidentGroup1 {
  noPatientConsent:          boolean; // Không có sự đồng ý của người bệnh/người nhà
  wrongProcedure:            boolean; // Thực hiện sai thủ thuật/quy trình/phương pháp điều trị
  forgottenInstruments:      boolean; // Bỏ sót dụng cụ trong quá trình PT
  deathDuringBirth:          boolean; // Tử vong khi sinh
  noIndication:              boolean; // Không thực hiện khi có chỉ định
  wrongPatient:              boolean; // Thực hiện sai người bệnh
  wrongSurgicalSite:         boolean; // Thực hiện sai vị trí phẫu thuật/thủ thuật
  deathDuringPregnancy:      boolean; // Tử vong trong thai kỳ
  neonatalDeath:             boolean; // Tử vong sơ sinh
  none:                      boolean; // Không
}

/** Group 2: Nhiễm khuẩn bệnh viện */
export interface IncidentGroup2 {
  bloodstreamInfection:      boolean; // Nhiễm khuẩn huyết
  pneumonia:                 boolean; // Viêm phổi
  otherInfections:           boolean; // Các loại nhiễm khuẩn khác
  surgicalSiteInfection:     boolean; // Nhiễm khuẩn vết mổ
  urinaryInfection:          boolean; // Nhiễm khuẩn tiết niệu
  none:                      boolean; // Không
}

/** Group 3: Thuốc và dịch truyền */
export interface IncidentGroup3 {
  wrongMedDispensed:         boolean; // Cấp phát sai thuốc, dịch truyền
  missingMedication:         boolean; // Thiếu thuốc
  wrongDose:                 boolean; // Sai liều, sai hàm lượng
  wrongTiming:               boolean; // Sai thời gian
  wrongOrder:                boolean; // Sai y lệnh
  missedDose:                boolean; // Bỏ sót thuốc/liều thuốc
  wrongMedication:           boolean; // Sai thuốc
  wrongPatient:              boolean; // Sai người bệnh
  wrongRoute:                boolean; // Sai đường dùng
  none:                      boolean; // Không
}

/** Group 4: Máu và chế phẩm máu */
export interface IncidentGroup4 {
  transfusionReaction:       boolean; // Phản ứng phụ, tai biến khi truyền máu
  wrongDoseTiming:           boolean; // Truyền sai liều, sai thời điểm
  wrongBloodProduct:         boolean; // Truyền nhầm máu, chế phẩm máu
  none:                      boolean; // Không
}

/** Group 5: Thiết bị y tế */
export interface IncidentGroup5 {
  lackOfManual:              boolean; // Thiếu thông tin hướng dẫn sử dụng
  deviceError:               boolean; // Lỗi thiết bị
  missingOrInappropriate:    boolean; // Thiết bị thiếu hoặc không phù hợp
  none:                      boolean; // Không
}

/** Group 6: Hành vi */
export interface IncidentGroup6 {
  selfHarmTendency:          boolean; // Khuynh hướng tự gây hại, tự tử
  sexualHarassByStaff:       boolean; // Quấy rối tình dục bởi nhân viên
  sexualHarassByPatient:     boolean; // Quấy rối tình dục bởi người bệnh/khách
  physicalAbuse:             boolean; // Xâm hại cơ thể bởi người bệnh/khách
  suicideAttempt:            boolean; // Có hành động tự tử
  elopement:                 boolean; // Trốn viện
  none:                      boolean; // Không
}

/** Group 7: Tai nạn đối với người bệnh */
export interface IncidentGroup7 {
  fall:                      boolean; // Té ngã
  none:                      boolean; // Không
  // 7.1 Hậu quả bị trượt ngã
  fallConsequenceNoEffect:   boolean;
  fallConsequenceSoftTissue: boolean;
  fallConsequenceFracture:   boolean;
  fallConsequenceDeath:      boolean;
  fallConsequenceAbrasion:   boolean;
  fallConsequenceOrgan:      boolean;
  fallConsequenceBrainTrauma:boolean;
  fallLocation:              string;  // 7.2 Địa điểm trượt ngã
}

/** Group 8: Hạ tầng cơ sở */
export interface IncidentGroup8 {
  damaged:                   boolean; // Bị hư hỏng, bị lỗi
  missingOrInappropriate:    boolean; // Thiếu hoặc không phù hợp
  none:                      boolean; // Không
}

/** Group 9: Quản lý nguồn lực, tổ chức */
export interface IncidentGroup9 {
  inadequateServices:        boolean; // Tính phù hợp, đầy đủ của dịch vụ khám bệnh, chữa bệnh
  inadequateResources:       boolean; // Tính phù hợp, đầy đủ của nguồn lực
  inadequatePolicies:        boolean; // Tính phù hợp, đầy đủ của chính sách, quy định, quy trình
  none:                      boolean; // Không
}

/** Group 10: Hồ sơ, tài liệu, thủ tục hành chính */
export interface IncidentGroup10 {
  missingDocuments:          boolean; // Tài liệu mất hoặc thiếu
  unclearDocuments:          boolean; // Tài liệu không rõ ràng, không hoàn chỉnh
  longWaitTime:              boolean; // Thời gian chờ đợi kéo dài
  lateDocuments:             boolean; // Cung cấp hồ sơ tài liệu chậm
  wrongDocuments:            boolean; // Nhầm hồ sơ tài liệu
  complexProcedures:         boolean; // Thủ tục hành chính phức tạp
  none:                      boolean; // Không
}

/** Group 11: Khác */
export interface IncidentGroup11 {
  notListedAbove:            boolean; // Các sự cố không đề cập trong mục 1-10
  otherReason:               string;  // Lý do khác (text)
}

/** All 11 incident type groups */
export interface IncidentTypeClassification {
  group1:  IncidentGroup1;
  group2:  IncidentGroup2;
  group3:  IncidentGroup3;
  group4:  IncidentGroup4;
  group5:  IncidentGroup5;
  group6:  IncidentGroup6;
  group7:  IncidentGroup7;
  group8:  IncidentGroup8;
  group9:  IncidentGroup9;
  group10: IncidentGroup10;
  group11: IncidentGroup11;
}

// ─────────────────────────────────────────────────────────────────────────────
// Section IV – Nhóm nguyên nhân (Cause category groups 1–4)
// ─────────────────────────────────────────────────────────────────────────────

/** Cause Group 1: Nhân viên */
export interface CauseGroup1 {
  knowledge:                 boolean; // Nhận thức (kiến thức, hiểu biết, quan niệm)
  practice:                  boolean; // Thực hành
  psychology:                boolean; // Tâm sinh lý, thể chất, bệnh lý
  attitude:                  boolean; // Thái độ, hành vi, cảm xúc
  communication:             boolean; // Giao tiếp
  socialFactors:             boolean; // Các yếu tố xã hội
  none:                      boolean; // Không
}

/** Cause Group 2: Người bệnh */
export interface CauseGroup2 {
  knowledge:                 boolean;
  practice:                  boolean;
  psychology:                boolean;
  attitude:                  boolean;
  communication:             boolean;
  socialFactors:             boolean;
  none:                      boolean;
}

/** Cause Group 3: Môi trường làm việc */
export interface CauseGroup3 {
  facilities:                boolean; // Cơ sở vật chất, hạ tầng, trang thiết bị
  safetyAssessment:          boolean; // Đánh giá về độ an toàn, các nguy cơ rủi ro
  regulations:               boolean; // Nội quy, quy định và đặc tính kỹ thuật
  distanceToWork:            boolean; // Khoảng cách đến nơi làm việc quá xa
  none:                      boolean;
}

/** Cause Group 4: Tổ chức/dịch vụ */
export interface CauseGroup4 {
  policies:                  boolean; // Các chính sách, quy trình, hướng dẫn chuyên môn
  culture:                   boolean; // Văn hóa tổ chức
  standardCompliance:        boolean; // Tuân thủ quy trình thực hành chuẩn
  teamwork:                  boolean; // Làm việc nhóm
  none:                      boolean;
}

/** All 4 cause category groups */
export interface IncidentCauseClassification {
  group1: CauseGroup1;
  group2: CauseGroup2;
  group3: CauseGroup3;
  group4: CauseGroup4;
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab 4A – Nhân viên chuyên trách analysis
// ─────────────────────────────────────────────────────────────────────────────

export interface StaffAnalysis {
  detailedDescription:       string;               // I. Mô tả chi tiết sự cố
  affectedSubjects:          string;               // Đối tượng chịu ảnh hưởng
  incidentLocation:          string;               // Địa điểm xảy ra sự cố
  incidentTypeGroups:        IncidentTypeClassification; // II. Phân loại theo nhóm sự cố
  treatmentOrders:           string;               // III. Điều trị/y lệnh đã được thực hiện
  causeGroups:               IncidentCauseClassification; // IV. Phân loại theo nhóm nguyên nhân
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab 4B – Cấp quản lý analysis (expandable later)
// ─────────────────────────────────────────────────────────────────────────────

export interface ManagementAnalysis {
  rootCauseAnalysis:         string;
  correctiveActions:         string;
  preventiveActions:         string;
  recommendations:           string;
  analysedBy:                string;
  analysisDate:              string | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main MedicalIncident entity
// ─────────────────────────────────────────────────────────────────────────────

export interface MedicalIncident extends Timestamps {
  id:                          UUID;
  incidentCode:                string;               // Mã sự cố y khoa (auto-generated)
  incidentName:                string;               // Tên sự cố y khoa

  // ─── Patient info ───────────────────────────────────
  patientCode:                 string;               // Mã bệnh nhân
  patientName:                 string;               // Họ tên
  patientDob:                  string | null;         // Ngày sinh
  patientGender:               string;               // Giới tính
  departmentId:                string;               // Khoa (id)
  departmentName:              string;               // Khoa (name)
  roomName:                    string;               // Phòng
  incidentCategoryCode:        string;               // Phân loại sự cố y khoa

  // ─── Report info ────────────────────────────────────
  reportType:                  IncidentReportType;   // Tự nguyện / Bắt buộc
  createdAt:                   string;               // Thời gian tạo
  createdById:                 UUID;
  createdByName:               string;               // Người tạo
  occurredAt:                  string | null;         // Thời gian xảy ra
  reportingDepartmentId:       string;               // Khoa báo cáo (id)
  reportingDepartmentName:     string;               // Khoa báo cáo (name)

  // ─── Incident subjects (checkboxes) ─────────────────
  subjectPatient:              boolean;              // Người bệnh
  subjectStaff:                boolean;              // Nhân viên y tế
  subjectVisitor:              boolean;              // Người nhà/khách đến thăm
  subjectEquipment:            boolean;              // Trang thiết bị/cơ sở hạ tầng

  // ─── Location ────────────────────────────────────────
  incidentDepartmentLocation:  string;               // Khoa/phòng/vị trí xảy ra sự cố
  specificLocation:            string;               // Vị trí cụ thể

  // ─── Brief description ───────────────────────────────
  briefDescription:            string;               // Mô tả ngắn gọn về sự cố
  initialSolution:             string;               // Đề xuất giải pháp ban đầu
  initialTreatment:            string;               // Điều trị/xử trí ban đầu đã được thực hiện

  // ─── Notifications ───────────────────────────────────
  notifyDoctor:                NotificationStatus;   // Thông báo cho Bác sĩ điều trị
  recordInMedicalRecord:       NotificationStatus;   // Ghi nhận vào hồ sơ bệnh án
  notifyFamily:                NotificationStatus;   // Thông báo cho người nhà/người bảo hộ
  notifyPatient:               NotificationStatus;   // Thông báo cho người bệnh

  // ─── Initial classification ──────────────────────────
  occurrenceStatus:            IncidentOccurrenceStatus; // Phân loại ban đầu
  severity:                    IncidentSeverity;     // Mức độ ảnh hưởng

  // ─── Reporter info ───────────────────────────────────
  reporterName:                string;               // Họ tên người thông báo
  reporterPhone:               string;               // Số điện thoại
  reporterEmail:               string;               // Email
  reporterIsNurse:             boolean;              // Điều dưỡng (chức danh)
  reporterIsPatient:           boolean;              // Người bệnh
  reporterIsVisitor:           boolean;              // Người nhà/khách đến thăm
  reporterIsDoctor:            boolean;              // Bác sĩ (chức danh)
  reporterIsOther:             boolean;              // Khác
  reporterOtherDetail:         string;               // Ghi cụ thể (nếu Khác)
  witness1:                    string;               // Người chứng kiến 1
  witness2:                    string;               // Người chứng kiến 2

  // ─── Status ──────────────────────────────────────────
  status:                      IncidentStatus;

  // ─── Analysis (Tab 4) ────────────────────────────────
  staffAnalysis:               StaffAnalysis | null;
  managementAnalysis:          ManagementAnalysis | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// List / Filter / Stats
// ─────────────────────────────────────────────────────────────────────────────

export interface MedicalIncidentFilters {
  search?:       string;
  status?:       IncidentStatus | '';
  severity?:     IncidentSeverity | '';
  departmentId?: string;
  dateFrom?:     string;
  dateTo?:       string;
  reportType?:   IncidentReportType | '';
}

// ─────────────────────────────────────────────────────────────────────────────
// Report / Statistics types
// ─────────────────────────────────────────────────────────────────────────────

export interface ChartDataItem {
  key:   string;
  label: string;
  count: number;
}

export interface GroupDetailItem {
  key:   string;
  label: string;
  count: number;
}

export interface GroupDetail {
  groupKey:   string;
  groupLabel: string;
  totalCount: number;
  items:      GroupDetailItem[];
}

export interface MedicalIncidentReport {
  dateFrom:   string;
  dateTo:     string;
  totalCount: number;
  // Tab 1
  byMonth:               ChartDataItem[];
  byReportType:          ChartDataItem[];
  byReportingDepartment: ChartDataItem[];
  byDepartment:          ChartDataItem[];
  byOccurrenceStatus:    ChartDataItem[];
  bySeverity:            ChartDataItem[];
  byAffectedSubject:     ChartDataItem[];
  // Tab 2 + 4
  byIncidentTypeGroup:      ChartDataItem[];
  incidentTypeGroupDetails: GroupDetail[];
  // Tab 2 + 5
  byCauseGroup:      ChartDataItem[];
  causeGroupDetails: GroupDetail[];
}

export interface MedicalIncidentReportFilters {
  year?:         number;
  dateFrom?:     string;
  dateTo?:       string;
  departmentId?: string;
}

export interface MedicalIncidentStats {
  total:       number;
  draft:       number;
  submitted:   number;
  inAnalysis:  number;
  resolved:    number;
  closed:      number;
  severeCount: number;
}

