/**
 * Report Models
 * Defines data structures for reporting and analytics
 */

export enum ReportCategory {
  Performance = 'performance',
  Compliance = 'compliance',
  Workload = 'workload',
  Quality = 'quality',
}

export enum ReportPeriod {
  Last7Days = 'last7days',
  Last30Days = 'last30days',
  ThisMonth = 'thisMonth',
  ThisQuarter = 'thisQuarter',
  ThisYear = 'thisYear',
  Custom = 'custom',
}

export interface ReportFilters {
  period: ReportPeriod;
  startDate?: string;
  endDate?: string;
  department?: string;
  team?: string;
}

// Ticket Performance Report
export interface TicketPerformanceMetrics {
  totalTickets: number;
  resolvedTickets: number;
  averageTimeHours: number;
  completionRate: number;
  trend: DataPoint[];
}

// Task Completion Report  
export interface TaskCompletionMetrics {
  totalTasks: number;
  completedTasks: number;
  overdueTasks: number;
  onTimeRate: number;
  trend: DataPoint[];
}

// Team Performance Report
export interface TeamPerformanceMember {
  id: string;
  name: string;
  avatar: string;
  ticketsResolved: number;
  tasksCompleted: number;
  averageTime: number;
}

// SLA Compliance Report
export interface SLAComplianceMetrics {
  overallCompliance: number;
  trend: DataPoint[];
  byPriority: {
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
  breaches: SLABreach[];
}

export interface SLABreach {
  ticketId: string;
  title: string;
  priority: 'critical' | 'high' | 'medium' | 'low';
  assignee: string;
  slaTarget: string;
  actualTime: string;
  breachTime: string;
  status: string;
}

// Workload Report
export interface WorkloadMetrics {
  currentWorkload: WorkloadItem[];
  capacityUtilization: {
    utilized: number;
    available: number;
  };
  backlog: {
    total: number;
    critical: number;
    high: number;
    medium: number;
  };
}

export interface WorkloadItem {
  userId: string;
  userName: string;
  avatar: string;
  activeTasksCount: number;
}

// Quality Report
export interface QualityMetrics {
  userSatisfaction: {
    averageRating: number;
    totalRatings: number;
    distribution: number[]; // [5star, 4star, 3star, 2star, 1star]
  };
  firstTimeFixRate: {
    fixedFirstTime: number;
    reopenRate: number;
    trend: DataPoint[];
  };
}

// Common data point for charts
export interface DataPoint {
  label: string;
  value: number;
}

// Complete Reports Data
export interface ReportsData {
  ticketPerformance: TicketPerformanceMetrics;
  taskCompletion: TaskCompletionMetrics;
  teamPerformance: TeamPerformanceMember[];
  slaCompliance: SLAComplianceMetrics;
  workload: WorkloadMetrics;
  quality: QualityMetrics;
}
