import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchMedicalIncidentById,
  createMedicalIncident,
  updateMedicalIncident,
  setSelectedIncident,
} from '../../store/slices/medicalIncidentsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { Button } from '../../components/common/Button';
import { Tabs } from '../../components/common/Tabs';
import { Tab1IncidentInfo } from './components/Tab1_IncidentInfo';
import { Tab4AStaffAnalysis } from './components/Tab4A_StaffAnalysis';
import { Tab4BManagementAnalysis } from './components/Tab4B_ManagementAnalysis';
import {
  MedicalIncident,
  IncidentStatus,
  StaffAnalysis,
  ManagementAnalysis,
  createEmptyMedicalIncident,
  createEmptyIncidentTypeGroups,
  createEmptyCauseGroups,
} from '../../models/MedicalIncident';
import styles from './MedicalIncidentFormPage.module.css';

// ─── Validation ────────────────────────────────────────────────────────────

type ValidationErrors = Record<string, string>;

/** Maps a validation error key to the section ID in Tab1 to scroll to */
const FIELD_TO_SECTION: Record<string, string> = {
  incidentName:     'field-section-report',
  occurredAt:       'field-section-report',
  patientName:      'field-section-patient',
  departmentId:     'field-section-patient',
  severity:         'field-section-classification',
  briefDescription: 'field-section-description',
};

function validateForm(form: Partial<MedicalIncident>, isDraft: boolean): ValidationErrors {
  const errors: ValidationErrors = {};

  // Always required (mirrors BFF [Required] attributes)
  if (!form.incidentName?.trim()) {
    errors.incidentName = 'Tên sự cố y khoa là bắt buộc';
  } else if (form.incidentName.length > 500) {
    errors.incidentName = 'Tên sự cố không được vượt quá 500 ký tự';
  }

  if (!form.patientName?.trim()) {
    errors.patientName = 'Họ tên bệnh nhân là bắt buộc';
  } else if (form.patientName.length > 200) {
    errors.patientName = 'Họ tên bệnh nhân không được vượt quá 200 ký tự';
  }

  // Additional fields required when submitting (not draft)
  if (!isDraft) {
    if (!form.occurredAt) {
      errors.occurredAt = 'Thời gian xảy ra là bắt buộc khi gửi báo cáo';
    }
    if (!form.departmentId) {
      errors.departmentId = 'Khoa là bắt buộc khi gửi báo cáo';
    }
    if (!form.briefDescription?.trim()) {
      errors.briefDescription = 'Mô tả sự cố là bắt buộc khi gửi báo cáo';
    }
    if (!form.severity) {
      errors.severity = 'Mức độ ảnh hưởng là bắt buộc khi gửi báo cáo';
    }
  }

  return errors;
}

// ─── Defaults ──────────────────────────────────────────────────────────────

const defaultStaffAnalysis = (): StaffAnalysis => ({
  detailedDescription: '',
  affectedSubjects: '',
  incidentLocation: '',
  incidentTypeGroups: createEmptyIncidentTypeGroups(),
  treatmentOrders: '',
  causeGroups: createEmptyCauseGroups(),
});

const defaultManagementAnalysis = (): ManagementAnalysis => ({
  rootCauseAnalysis: '',
  correctiveActions: '',
  preventiveActions: '',
  recommendations: '',
  analysedBy: '',
  analysisDate: null,
});

/**
 * Deep-merge a loaded StaffAnalysis with defaults so that any field that is
 * missing from older/partial stored JSON falls back to a safe initial value.
 */
function mergeStaffAnalysis(loaded: StaffAnalysis | null): StaffAnalysis {
  const def      = defaultStaffAnalysis();
  if (!loaded) return def;
  const defG = def.incidentTypeGroups;
  const defC = def.causeGroups;
  return {
    ...def,
    ...loaded,
    incidentTypeGroups: {
      group1:  { ...defG.group1,  ...loaded.incidentTypeGroups?.group1  },
      group2:  { ...defG.group2,  ...loaded.incidentTypeGroups?.group2  },
      group3:  { ...defG.group3,  ...loaded.incidentTypeGroups?.group3  },
      group4:  { ...defG.group4,  ...loaded.incidentTypeGroups?.group4  },
      group5:  { ...defG.group5,  ...loaded.incidentTypeGroups?.group5  },
      group6:  { ...defG.group6,  ...loaded.incidentTypeGroups?.group6  },
      group7:  { ...defG.group7,  ...loaded.incidentTypeGroups?.group7  },
      group8:  { ...defG.group8,  ...loaded.incidentTypeGroups?.group8  },
      group9:  { ...defG.group9,  ...loaded.incidentTypeGroups?.group9  },
      group10: { ...defG.group10, ...loaded.incidentTypeGroups?.group10 },
      group11: { ...defG.group11, ...loaded.incidentTypeGroups?.group11 },
    },
    causeGroups: {
      group1: { ...defC.group1, ...loaded.causeGroups?.group1 },
      group2: { ...defC.group2, ...loaded.causeGroups?.group2 },
      group3: { ...defC.group3, ...loaded.causeGroups?.group3 },
      group4: { ...defC.group4, ...loaded.causeGroups?.group4 },
    },
  };
}

/**
 * Deep-merge a loaded ManagementAnalysis with defaults.
 */
function mergeManagementAnalysis(loaded: ManagementAnalysis | null): ManagementAnalysis {
  return { ...defaultManagementAnalysis(), ...loaded };
}

// ─── Component ─────────────────────────────────────────────────────────────

const MedicalIncidentFormPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate   = useNavigate();
  const dispatch   = useAppDispatch();
  const isNew      = !id || id === 'new';

  const { selectedIncident, saving, loading } = useAppSelector((s) => s.medicalIncidents);
  const authUser = useAppSelector((s) => s.auth.user);

  const [activeTab, setActiveTab] = useState('incident');
  const [analysisTab, setAnalysisTab] = useState('staff');
  const [form, setForm] = useState<Partial<MedicalIncident>>({});
  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});

  // Load existing incident
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isNew && id) {
        dispatch(fetchMedicalIncidentById(id));
      } else {
        dispatch(setSelectedIncident(null));
      }
    }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, id, isNew]);

  // Populate form from loaded incident or init new
  useEffect(() => {
    if (!isNew && selectedIncident) {
      setForm({
        ...selectedIncident,
        staffAnalysis:      mergeStaffAnalysis(selectedIncident.staffAnalysis),
        managementAnalysis: mergeManagementAnalysis(selectedIncident.managementAnalysis),
      });
    } else if (isNew) {
      const now = new Date().toISOString();
      setForm({
        ...createEmptyMedicalIncident(),
        createdAt: now,
        createdById: authUser?.id ?? '',
        createdByName: authUser?.fullName ?? '',
        staffAnalysis: defaultStaffAnalysis(),
        managementAnalysis: defaultManagementAnalysis(),
      });
    }
  }, [isNew, selectedIncident, authUser]);

  const patch = (p: Partial<MedicalIncident>) => {
    setForm((prev) => ({ ...prev, ...p }));
    // Clear validation errors for any patched fields
    const patchedKeys = Object.keys(p);
    setValidationErrors((prev) => {
      if (!patchedKeys.some((k) => k in prev)) return prev;
      const next = { ...prev };
      patchedKeys.forEach((k) => delete next[k]);
      return next;
    });
  };

  const scrollToFirstError = (errors: ValidationErrors) => {
    const firstKey = Object.keys(errors)[0];
    const sectionId = FIELD_TO_SECTION[firstKey];
    if (sectionId) {
      setTimeout(() => {
        document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 120);
    }
  };

  const handleSave = async (asDraft = false) => {
    const errors = validateForm(form, asDraft);

    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      // Switch to Tab 1 so the user can see the errors
      if (activeTab !== 'incident') {
        setActiveTab('incident');
      }
      scrollToFirstError(errors);
      return;
    }

    setValidationErrors({});

    const data: Partial<MedicalIncident> = {
      ...form,
      status: asDraft ? IncidentStatus.Draft : IncidentStatus.Submitted,
    };

    try {
      if (isNew) {
        await dispatch(createMedicalIncident(data)).unwrap();
        dispatch(addToast({ message: asDraft ? 'Lưu nháp sự cố y khoa thành công' : 'Tạo sự cố y khoa thành công', type: 'success' }));
        navigate('/medical-incidents', { replace: true });
      } else {
        await dispatch(updateMedicalIncident({ id: id!, data })).unwrap();
        dispatch(addToast({ message: 'Cập nhật sự cố y khoa thành công', type: 'success' }));
      }
    } catch (error: unknown) {
      const message = error instanceof Error
        ? error.message
        : 'Đã có lỗi xảy ra, vui lòng thử lại';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const handleBack = () => navigate('/medical-incidents');

  if (loading && !isNew) {
    return (
      <div className={styles.loadingWrap}>
        <i className="fas fa-spinner fa-spin" /> Đang tải...
      </div>
    );
  }

  const mainTabs = [
    { id: 'incident',    label: 'Sự Cố Y Khoa',          icon: 'fas fa-hospital-user' },
    { id: 'attachments', label: 'Tài Liệu Đính Kèm',     icon: 'fas fa-paperclip'     },
    { id: 'resolution',  label: 'Bằng Chứng Giải Quyết', icon: 'fas fa-check-square'  },
    { id: 'analysis',    label: 'Tìm Hiểu, Phân Tích',   icon: 'fas fa-search'        },
  ];

  const hasErrors = Object.keys(validationErrors).length > 0;

  return (
    <div className={styles.page}>
      {/* ── Sticky band: header + tabs ─────────────────────────────────── */}
      <div className={styles.stickyTop}>
        {/* Page header */}
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button className={styles.backBtn} onClick={handleBack}>
              <i className="fas fa-arrow-left" />
            </button>
            <div>
              <h1 className={styles.title}>
                {isNew ? 'Thêm sự cố y khoa mới' : `Sự cố: ${form.incidentCode || '...'}`}
              </h1>
              {!isNew && form.incidentName && (
                <p className={styles.subtitle}>{form.incidentName}</p>
              )}
            </div>
          </div>
          <div className={styles.headerActions}>
            {(isNew || form.status === IncidentStatus.Draft) && (
              <Button variant="secondary" onClick={() => handleSave(true)} disabled={saving}>
                <i className="fas fa-save" /> Lưu nháp
              </Button>
            )}
            <Button variant="primary" onClick={() => handleSave(false)} disabled={saving}>
              {saving
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-paper-plane" /> {isNew ? 'Gửi báo cáo' : 'Cập nhật'}</>
              }
            </Button>
          </div>
        </div>

        {/* Main tabs */}
        <div className={styles.tabsWrapper}>
          <Tabs
            tabs={mainTabs}
            activeTab={activeTab}
            onTabChange={(tab) => {
              setActiveTab(tab);
              // Clear errors when user manually switches to incident tab
              if (tab === 'incident') setValidationErrors({});
            }}
            variant="default"
          />
        </div>

        {/* ── Validation error banner (inside sticky so always visible) ── */}
        {hasErrors && activeTab === 'incident' && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div>
              <strong>Vui lòng điền đầy đủ các trường bắt buộc:</strong>
              <ul>
                {Object.values(validationErrors).map((msg, i) => (
                  <li key={i}>{msg}</li>
                ))}
              </ul>
            </div>
            <button
              className={styles.errorBannerClose}
              onClick={() => setValidationErrors({})}
              aria-label="Đóng"
            >
              <i className="fas fa-times" />
            </button>
          </div>
        )}
      </div>

      {/* ── Tab content ───────────────────────────────────────────────── */}
      <div className={styles.tabContent}>
        {/* Tab 1: Sự Cố Y Khoa */}
        {activeTab === 'incident' && (
          <Tab1IncidentInfo
            form={form}
            onChange={patch}
            isNew={isNew}
            errors={validationErrors}
          />
        )}

        {/* Tab 2: Tài Liệu Đính Kèm */}
        {activeTab === 'attachments' && (
          <div className={styles.emptyTab}>
            <i className="fas fa-paperclip" />
            <h3>Tài Liệu Đính Kèm</h3>
            <p>Chức năng đính kèm tài liệu sẽ được triển khai trong phiên bản tiếp theo.</p>
          </div>
        )}

        {/* Tab 3: Bằng Chứng Giải Quyết */}
        {activeTab === 'resolution' && (
          <div className={styles.emptyTab}>
            <i className="fas fa-check-square" />
            <h3>Bằng Chứng Giải Quyết</h3>
            <p>Chức năng quản lý bằng chứng giải quyết sẽ được triển khai trong phiên bản tiếp theo.</p>
          </div>
        )}

        {/* Tab 4: Tìm Hiểu, Phân Tích */}
        {activeTab === 'analysis' && (
          <div className={styles.analysisContainer}>
            {/* Sub-tab header */}
            <div className={styles.subTabBar}>
              <button
                className={`${styles.subTab} ${analysisTab === 'staff' ? styles.subTabActive : ''}`}
                onClick={() => setAnalysisTab('staff')}
              >
                A. Dành cho nhân viên chuyên trách
              </button>
              <button
                className={`${styles.subTab} ${analysisTab === 'management' ? styles.subTabActive : ''}`}
                onClick={() => setAnalysisTab('management')}
              >
                B. Dành cho cấp quản lý
              </button>
            </div>

            {analysisTab === 'staff' && form.staffAnalysis && (
              <Tab4AStaffAnalysis
                data={form.staffAnalysis}
                onChange={(p) => patch({ staffAnalysis: { ...form.staffAnalysis!, ...p } })}
              />
            )}
            {analysisTab === 'management' && form.managementAnalysis && (
              <Tab4BManagementAnalysis
                data={form.managementAnalysis}
                onChange={(p) => patch({ managementAnalysis: { ...form.managementAnalysis!, ...p } })}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default MedicalIncidentFormPage;
