import React, { useState } from 'react';
import { SLAAlert, CandidateSuggestion } from '../../../models/SLAAlert';
import { Slideout } from '../../common/Slideout';
import './AlertActionModals.css';

interface EscalateModalProps {
  alert: SLAAlert | null;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (alertId: string, reason: string, escalateTo?: string) => void;
  loading?: boolean;
}

export const EscalateModal: React.FC<EscalateModalProps> = ({
  alert,
  isOpen,
  onClose,
  onConfirm,
  loading,
}) => {
  const [reason, setReason] = useState('');
  const [escalateTo, setEscalateTo] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (alert && reason.trim()) {
      onConfirm(alert.id, reason.trim(), escalateTo || undefined);
      setReason('');
      setEscalateTo('');
    }
  };

  const handleClose = () => {
    setReason('');
    setEscalateTo('');
    onClose();
  };

  const handleConfirmSubmit = () => {
    handleSubmit(new Event('submit') as any);
  };

  if (!alert) return null;

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleClose} 
      title="Leo thang cảnh báo SLA"
      width="600px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleClose,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang xử lý...' : 'Leo thang',
        rightAction: handleConfirmSubmit,
        rightDisabled: !reason.trim() || loading,
      }}
    >
      <form className="alert-action-form">
        <div className="alert-action-form__info">
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Cảnh báo:</span>
            <span className="alert-action-form__value">{alert.title}</span>
          </div>
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Mã:</span>
            <span className="alert-action-form__value">{alert.relatedId}</span>
          </div>
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Mức độ hiện tại:</span>
            <span className="alert-action-form__value">Leo thang {alert.escalationLevel} lần</span>
          </div>
        </div>

        <div className="alert-action-form__field">
          <label htmlFor="escalate-to" className="alert-action-form__field-label">
            Leo thang đến (tùy chọn)
          </label>
          <input
            type="text"
            id="escalate-to"
            className="alert-action-form__input"
            value={escalateTo}
            onChange={(e) => setEscalateTo(e.target.value)}
            placeholder="Nhập tên người quản lý cấp cao hơn"
          />
          <span className="alert-action-form__hint">
            Để trống để leo thang theo cấp bậc tự động
          </span>
        </div>

        <div className="alert-action-form__field">
          <label htmlFor="escalate-reason" className="alert-action-form__field-label required">
            Lý do leo thang
          </label>
          <textarea
            id="escalate-reason"
            className="alert-action-form__textarea"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Mô tả lý do leo thang cảnh báo này..."
            rows={4}
            required
          />
        </div>
      </form>
    </Slideout>
  );
};


interface ReassignModalProps {
  alert: SLAAlert | null;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (
    alertId: string,
    relatedId: string,
    type: 'ticket' | 'task',
    newAssigneeId: string,
    newAssigneeName: string,
    reason: string
  ) => void;
  candidates?: CandidateSuggestion[];
  loading?: boolean;
  candidatesLoading?: boolean;
}

export const ReassignModal: React.FC<ReassignModalProps> = ({
  alert,
  isOpen,
  onClose,
  onConfirm,
  candidates = [],
  loading,
  candidatesLoading,
}) => {
  const [selectedUserId, setSelectedUserId] = useState('');
  const [reason, setReason] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (alert && selectedUserId && reason.trim()) {
      const selectedCandidate = candidates.find((c) => c.userId === selectedUserId);
      if (selectedCandidate) {
        onConfirm(
          alert.id,
          alert.relatedId,
          alert.type,
          selectedUserId,
          selectedCandidate.userName,
          reason.trim()
        );
        setSelectedUserId('');
        setReason('');
      }
    }
  };

  const handleClose = () => {
    setSelectedUserId('');
    setReason('');
    onClose();
  };

  const handleConfirmSubmit = () => {
    handleSubmit(new Event('submit') as any);
  };

  if (!alert) return null;

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleClose} 
      title="Chuyển giao công việc"
      width="600px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleClose,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang xử lý...' : 'Chuyển giao',
        rightAction: handleConfirmSubmit,
        rightDisabled: !selectedUserId || !reason.trim() || loading,
      }}
    >
      <form className="alert-action-form">
        <div className="alert-action-form__info">
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Cảnh báo:</span>
            <span className="alert-action-form__value">{alert.title}</span>
          </div>
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Mã:</span>
            <span className="alert-action-form__value">{alert.relatedId}</span>
          </div>
          <div className="alert-action-form__info-row">
            <span className="alert-action-form__label">Người hiện tại:</span>
            <span className="alert-action-form__value">{alert.assigneeName}</span>
          </div>
        </div>

        <div className="alert-action-form__field">
          <label htmlFor="reassign-user" className="alert-action-form__field-label required">
            Chuyển đến
          </label>
          {candidatesLoading ? (
            <div className="alert-action-form__loading">Đang tải danh sách ứng viên...</div>
          ) : candidates.length > 0 ? (
            <select
              id="reassign-user"
              className="alert-action-form__select"
              value={selectedUserId}
              onChange={(e) => setSelectedUserId(e.target.value)}
              required
            >
              <option value="">-- Chọn người nhận --</option>
              {candidates.map((candidate) => (
                <option key={candidate.userId} value={candidate.userId}>
                  {candidate.userName} - {candidate.departmentName} (Khả dụng: {candidate.availabilityScore}%)
                </option>
              ))}
            </select>
          ) : (
            <div className="alert-action-form__empty">Không có ứng viên phù hợp</div>
          )}
        </div>

        <div className="alert-action-form__field">
          <label htmlFor="reassign-reason" className="alert-action-form__field-label required">
            Lý do chuyển giao
          </label>
          <textarea
            id="reassign-reason"
            className="alert-action-form__textarea"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Mô tả lý do chuyển giao công việc này..."
            rows={4}
            required
          />
        </div>
      </form>
    </Slideout>
  );
};
