/**
 * Pure mapping: BFF DTO → frontend Task model.
 */

import { Task, TaskActivityItem } from '../../models/Task';
import { PaginatedResponse, UUID } from '../../models/common';
import { BffTaskDto, BffTaskActivityDto, BffTaskPagedDto, BffTaskListItemDto } from './responseModel';

/** BFF TaskActivityDto → frontend TaskActivityItem */
const mapTaskActivity = (a: BffTaskActivityDto): TaskActivityItem => ({
  id:          a.id as UUID,
  type:        a.type,
  actor:       a.actorName,
  description: a.description,
  timestamp:   a.createdAt,
  fromStatus:  a.fromStatus ?? null,
  toStatus:    a.toStatus   ?? null,
});

export const mapBffTask = (dto: BffTaskDto): Task => ({
  id:                    dto.id,
  ticketId:              dto.ticketId ?? '',
  ticketNumber:          dto.ticketNumber,
  title:                 dto.title,
  description:           dto.description,
  status:                dto.status as Task['status'],
  priority:              dto.priority as Task['priority'],
  progress:              dto.progress,
  assignmentStrategy:    dto.assignmentStrategy as Task['assignmentStrategy'],
  assigneeId:            dto.assigneeId,
  assigneeName:          dto.assigneeName,
  assignToDepartmentId:  dto.assignToDepartmentId,
  assignToDepartmentName: dto.assignToDepartmentName,
  creatorId:             dto.creatorId,
  creatorName:           dto.creatorName,
  estimatedHours:        dto.estimatedHours,
  actualHours:           dto.actualHours,
  dueDate:               dto.dueDate || '',
  skillsRequired:        dto.skillsRequired ?? [],
  subtasks:              dto.subtasks ?? [],
  category:              dto.category,
  departmentId:          dto.departmentId,
  departmentName:        dto.departmentName,
  tags:                  dto.tags,
  slaRemaining:          dto.slaRemaining,
  completedSubtasks:     dto.completedSubtasks,
  totalSubtasks:         dto.totalSubtasks,
  activities:            (dto.activities ?? []).map(mapTaskActivity),
  collaborators:         dto.collaborators?.map((c) => ({
    ...c,
    assignedByName: c.assignedByName,
  })),
  supportRequest:        dto.supportRequest,
  reassignmentRequest:   dto.reassignmentRequest,
  blocker:               dto.blocker,
  changesRequest:        dto.changesRequest,
  supportRequestedAt:    dto.supportRequestedAt,
  cancellationReason:    dto.cancellationReason,
  cancelledAt:           dto.cancelledAt,
  cancelledBy:           dto.cancelledBy,
  cancelledByName:       dto.cancelledByName,
  createdAt:             dto.createdAt,
  updatedAt:             dto.updatedAt,
});

export const mapBffTaskListItem = (dto: BffTaskListItemDto): Task => ({
  id:                    dto.id,
  ticketId:              dto.ticketId ?? '',
  ticketNumber:          dto.taskNumber,
  title:                 dto.title,
  description:           '',
  status:                dto.status as Task['status'],
  priority:              dto.priority as Task['priority'],
  progress:              dto.progress,
  assignmentStrategy:    dto.assignmentStrategy as Task['assignmentStrategy'],
  assigneeId:            dto.assigneeId,
  assigneeName:          dto.assigneeName,
  assignToDepartmentId:  undefined,
  assignToDepartmentName: undefined,
  creatorId:             '',
  creatorName:           '',
  estimatedHours:        0,
  actualHours:           0,
  dueDate:               dto.dueDate || '',
  skillsRequired:        [],
  subtasks:              [],
  category:              dto.category,
  departmentId:          undefined,
  departmentName:        undefined,
  tags:                  [],
  slaRemaining:          undefined,
  completedSubtasks:     0,
  totalSubtasks:         0,
  collaborators:         [],
  createdAt:             dto.createdAt,
  updatedAt:             dto.updatedAt,
});

export const mapBffTaskPaged = (dto: BffTaskPagedDto): PaginatedResponse<Task> => ({
  items:      dto.items.map(mapBffTaskListItem),
  total:      dto.totalCount,
  page:       dto.page,
  pageSize:   dto.pageSize,
  totalPages: dto.totalPages,
});
