import React, { useState, useRef, useEffect } from 'react';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './ButtonList.module.css';

export interface ButtonListProps {
  children: React.ReactNode;
  mainButtonIndex?: number; // Index of the button to show as main on mobile (default: 0)
  className?: string;
}

/**
 * ButtonList Component
 * 
 * Responsive button container that adapts to mobile:
 * - Desktop/Tablet: Shows all buttons horizontally
 * - Mobile with 1-2 buttons: Shows all buttons normally
 * - Mobile with 3+ buttons: Shows main button + dropdown for others
 */
export const ButtonList: React.FC<ButtonListProps> = ({
  children,
  mainButtonIndex = 0,
  className = '',
}) => {
  const { isMobile } = useResponsive();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Convert children to array
  const childArray = React.Children.toArray(children);
  const buttonCount = childArray.length;

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };

    if (isDropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isDropdownOpen]);

  // Desktop/Tablet OR Mobile with 1-2 buttons: Show all normally
  if (!isMobile || buttonCount <= 2) {
    return (
      <div className={`${styles.buttonList} ${className}`}>
        {children}
      </div>
    );
  }

  // Mobile with 3+ buttons: Show main button + dropdown
  const mainButton = childArray[mainButtonIndex];
  const dropdownButtons = childArray.filter((_, index) => index !== mainButtonIndex);

  return (
    <div className={`${styles.buttonListMobile} ${className}`} ref={dropdownRef}>
      {/* Main Button */}
      <div className={styles.mainButton}>
        {mainButton}
      </div>

      {/* Dropdown Toggle Button */}
      <button
        className={styles.dropdownToggle}
        onClick={() => setIsDropdownOpen(!isDropdownOpen)}
        type="button"
      >
        <i className={`fas fa-ellipsis-v ${styles.dropdownIcon}`}></i>
      </button>

      {/* Dropdown Menu */}
      {isDropdownOpen && (
        <div className={styles.dropdownMenu}>
          {dropdownButtons.map((button, index) => (
            <div
              key={index}
              className={styles.dropdownItem}
              onClick={() => setIsDropdownOpen(false)}
            >
              {button}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
