// Department assignment workflows
export const fetchDepartmentTasks = createAsyncThunk(
  'tasks/fetchDepartmentTasks',
  async (departmentId: UUID) => {
    const response = await taskService.taskService.getDepartmentTasks(departmentId);
    return response;
  }
);

export const claimDepartmentTask = createAsyncThunk(
  'tasks/claimDepartmentTask',
  async (taskId: UUID) => {
    const response = await taskService.taskService.claimDepartmentTask(taskId);
    return response;
  }
);

const tasksSlice = createSlice({
  name: 'tasks',
  initialState,
  reducers: {
    setFilters: (state, action: PayloadAction<TaskFilters>) => {
      state.filters = action.payload;
    },
    setSelectedTask: (state, action: PayloadAction<Task | null>) => {
      state.selectedTask = action.payload;
    },
    clearError: (state) => {
      state.error = null;
    },
    setPage: (state, action: PayloadAction<number>) => {
      state.pagination.page = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch tasks
      .addCase(fetchTasks.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchTasks.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload.items;
        state.pagination = {
          page: action.payload.page,
          pageSize: action.payload.pageSize,
          totalCount: action.payload.total,
        };
      })
      .addCase(fetchTasks.rejected, (state, action) => {
        if (action.meta.aborted) return;
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch tasks';
      })
      // Fetch pool tasks
      .addCase(fetchPoolTasks.fulfilled, (state, action) => {
        state.poolTasks = action.payload;
      })
      // Fetch pool stats
      .addCase(fetchPoolTaskStats.pending, (state) => {
        state.poolStats.loading = true;
      })
      .addCase(fetchPoolTaskStats.fulfilled, (state, action) => {
        state.poolStats = { ...action.payload, loading: false };
      })
      .addCase(fetchPoolTaskStats.rejected, (state, action) => {
        if (action.meta.aborted) return;
        state.poolStats.loading = false;
      })
      // Fetch single task
      .addCase(fetchTaskById.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchTaskById.fulfilled, (state, action) => {
        state.loading = false;
        state.selectedTask = action.payload;
      })
      .addCase(fetchTaskById.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch task';
      })
      // Create task
      .addCase(createTask.fulfilled, (state, action) => {
        state.items.unshift(action.payload);
      })
      // Claim task
      .addCase(claimTask.fulfilled, (state, action) => {
        // Remove from pool and add to user's tasks
        state.poolTasks = state.poolTasks.filter((t) => t.id !== action.payload.id);
        state.items.unshift(action.payload);
      })
      // Update task
      .addCase(updateTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Complete task
      .addCase(completeTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Submit for review
      .addCase(submitForReview.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Workflow actions - Request Support
      .addCase(requestSupport.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Assign Collaborator
      .addCase(assignCollaborator.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Request Reassignment
      .addCase(requestReassignment.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Approve Reassignment
      .addCase(approveReassignment.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Mark Blocked
      .addCase(markBlocked.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Unblock Task
      .addCase(unblockTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Approve Task
      .addCase(approveTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Request Changes
      .addCase(requestChanges.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Cancel Task
      .addCase(cancelTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Start Task
      .addCase(startTask.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTask?.id === action.payload.id) {
          state.selectedTask = action.payload;
        }
      })
      // Department tasks
      .addCase(fetchDepartmentTasks.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchDepartmentTasks.fulfilled, (state, action) => {
        state.departmentTasks = action.payload;
        state.loading = false;
      })
      .addCase(fetchDepartmentTasks.rejected, (state, action) => {
        if (action.meta.aborted) return;
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch department tasks';
      })
      .addCase(claimDepartmentTask.fulfilled, (state, action) => {
        // Remove task from department tasks
        state.departmentTasks = state.departmentTasks.filter((t) => t.id !== action.payload.id);
        // Update in main items if present
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
      });
  },
});

export const { setFilters, setSelectedTask, clearError, setPage } = tasksSlice.actions;
export default tasksSlice.reducer;
