import React, { useState, useMemo, useEffect } from 'react';
import { Ticket } from '../../../models/Ticket';
import { Task } from '../../../models/Task';
import { Card, Tabs, Tab } from '../../../components/common';
import { ChatTab, CommentsTab, ActivityTab, ActivityType, AttachmentsTab } from '../../../components/shared';
import type { Activity } from '../../../components/shared';
import { taskEndpoint } from '../../../services/task/endpoint';
import { useAppSelector } from '../../../store/hooks';
import { useAppToast } from '../../../hooks/useAppToast';
import { useMessages } from '../../../hooks/useMessages';
import styles from './TicketTabs.module.css';

interface TicketTabsProps {
  ticket: Ticket;
}

type TabType = 'chat' | 'comments' | 'activity' | 'attachments' | 'tasks';

const TicketTabs: React.FC<TicketTabsProps> = ({ ticket }) => {
  const [activeTab, setActiveTab]         = useState<TabType>('chat');
  const [ticketTasks, setTicketTasks]     = useState<Task[]>([]);
  const currentUser = useAppSelector((state) => state.auth.user);
  const toast = useAppToast();

  // ── Unified messages (replaces old inline comment + chat logic) ────────────
  const {
    chatMessages,
    comments,
    sendMessage,
    addComment,
    editComment,
    deleteComment,
    chatCount,
    commentCount,
    hasMoreChat,
    hasMoreComments,
    loadMoreChat,
    loadMoreComments,
    loading,
  } = useMessages('ticket', ticket.id);

  // ── Load tasks linked to this ticket ───────────────────────────────────────
  useEffect(() => {
    let unmounted = false;
    taskEndpoint.getTasks({ ticketId: ticket.id }, 1, 100)
      .then((res) => { if (!unmounted) setTicketTasks(res.items); })
      .catch((err: unknown) => {
        console.warn('[TicketTabs] Failed to load tasks:', err);
        toast.fromError(err, 'Không thể tải công việc, vui lòng thử lại');
      });
    return () => { unmounted = true; };
  }, [ticket.id]);

  // Define tabs configuration with overflow detection support
  const tabs: Tab[] = useMemo(
    () => [
      {
        id: 'chat',
        label: 'Trao đổi',
        icon: 'fas fa-comments',
        badge: chatCount,
        badgeColor: 'primary' as const,
      },
      {
        id: 'comments',
        label: 'Bình luận',
        icon: 'fas fa-comment-dots',
        badge: commentCount,
        badgeColor: 'gray' as const,
      },
      {
        id: 'tasks',
        label: 'Công việc',
        icon: 'fas fa-tasks',
        badge: ticketTasks.length,
        badgeColor: 'gray' as const,
      },
      {
        id: 'activity',
        label: 'Lịch sử',
        icon: 'fas fa-history',
      },
      {
        id: 'attachments',
        label: 'Tệp đính kèm',
        icon: 'fas fa-paperclip',
        badge: ticket.attachmentCount || 0,
        badgeColor: 'gray' as const,
      },
    ],
    [chatCount, commentCount, ticketTasks.length, ticket.attachmentCount]
  );

  const renderTabContent = () => {
    switch (activeTab) {
      case 'chat':
        return (
          <ChatTab
            entityId={ticket.id}
            entityType="ticket"
            messages={chatMessages}
            currentUserId={currentUser?.id}
            onSendMessage={sendMessage}
            hasMore={hasMoreChat}
            loading={loading}
            onLoadMore={loadMoreChat}
          />
        );
      case 'comments':
        return (
          <CommentsTab
            entityId={ticket.id}
            entityType="ticket"
            comments={comments}
            currentUserId={currentUser?.id}
            onAddComment={addComment}
            onEditComment={editComment}
            onDeleteComment={deleteComment}
            hasMore={hasMoreComments}
            loading={loading}
            onLoadMore={loadMoreComments}
          />
        );
      case 'activity': {
        const activities: Activity[] = (ticket.activities ?? []).map((a) => ({
          id:          a.id,
          entityId:    ticket.id,
          type:        a.type as ActivityType,
          actor:       a.actor,
          description: a.description,
          timestamp:   a.timestamp,
          metadata:    (a.fromStatus || a.toStatus)
            ? { fromStatus: a.fromStatus, toStatus: a.toStatus }
            : undefined,
        }));
        return (
          <ActivityTab
            entityId={ticket.id}
            entityType="ticket"
            activities={activities}
          />
        );
      }
      case 'tasks':
        return (
          <div className={styles.taskList}>
            {ticketTasks.length === 0 ? (
              <div className={styles.emptyTasks}>
                <i className="fas fa-tasks"></i>
                <span>Chưa có công việc nào được liên kết với phiếu này</span>
              </div>
            ) : (
              ticketTasks.map((t) => (
                <div key={t.id} className={styles.taskItem}>
                  <div className={styles.taskItemLeft}>
                    <span className={styles.taskNumber}>{`#${t.id.slice(0, 6).toUpperCase()}`}</span>
                    <span className={styles.taskTitle}>{t.title}</span>
                  </div>
                  <div className={styles.taskItemRight}>
                    {t.assigneeName && (
                      <span className={styles.taskAssignee}>
                        <i className="fas fa-user"></i> {t.assigneeName}
                      </span>
                    )}
                    <span className={`${styles.taskStatus} ${styles[`status_${t.status}`]}`}>
                      {t.status.replace('_', ' ')}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        );
      case 'attachments':
        return (
          <AttachmentsTab
            entityId={ticket.id}
            entityType="ticket"
            attachments={[]}
            onUpload={async (files) => {
              console.log('Upload ticket files:', files);
              // TODO: Call API to upload files
            }}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Card>
      <div className={styles.tabsHeader}>
        <Tabs
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={(tabId) => setActiveTab(tabId as TabType)}
          variant="underline"
        />
      </div>
      <div className={styles.tabContent}>{renderTabContent()}</div>
    </Card>
  );
};

export default TicketTabs;
